import pytest

def is_palindrome(s: str) -> bool:
    s = s.lower().replace(' ', '')
    return s == s[::-1]


class TestIsPalindromeHappyPath:
    """Tests for typical palindrome cases."""

    def test_simple_palindrome(self):
        assert is_palindrome("racecar") is True

    def test_single_word_with_spaces(self):
        assert is_palindrome("race car") is True

    def test_mixed_case_palindrome(self):
        assert is_palindrome("RaceCar") is True

    def test_palindrome_with_multiple_words(self):
        assert is_palindrome("a man a plan a canal panama") is True

    def test_numeric_string_palindrome(self):
        assert is_palindrome("12321") is True

    def test_alphanumeric_palindrome(self):
        assert is_palindrome("a1b1a") is True


class TestIsPalindromeNonPalindromes:
    """Tests for non-palindrome strings."""

    def test_simple_non_palindrome(self):
        assert is_palindrome("hello") is False

    def test_non_palindrome_with_spaces(self):
        assert is_palindrome("not a palindrome") is False

    def test_non_palindrome_mixed_case(self):
        assert is_palindrome("HelloWorld") is False


class TestIsPalindromeEdgeCases:
    """Tests for edge cases."""

    def test_empty_string(self):
        # Empty string is trivially a palindrome
        assert is_palindrome("") is True

    def test_single_character(self):
        assert is_palindrome("a") is True

    def test_single_character_non_alpha(self):
        assert is_palindrome("1") is True

    def test_only_spaces(self):
        # All spaces become empty after replace
        assert is_palindrome("   ") is True

    def test_special_characters(self):
        # Special chars are not removed, so check if they match
        assert is_palindrome("!@") is False


class TestIsPalindromeErrorCases:
    """Tests for invalid inputs."""

    def test_none_input(self):
        with pytest.raises(AttributeError):
            is_palindrome(None)

    def test_integer_input(self):
        with pytest.raises(TypeError):
            is_palindrome(123)

    def test_list_input(self):
        with pytest.raises(TypeError):
            is_palindrome(["a", "b", "c"])

    def test_dict_input(self):
        with pytest.raises(TypeError):
            is_palindrome({"key": "value"})
